import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.*;

/**
 * Asia Pacific Airport Simulation
 * Implements Semaphore for resource limiting and ReentrantLock for mutual exclusion.
 */
public class AirportSimulation {
    private static final int MAX_PLANES_ON_GROUND = 3;
    private static final int NUM_GATES = 3;

    // Concurrency Facilities
    private static final Semaphore runway = new Semaphore(1, true);
    private static final Semaphore groundCapacity = new Semaphore(MAX_PLANES_ON_GROUND, true);
    private static final Semaphore gates = new Semaphore(NUM_GATES, true);
    private static final Semaphore refuelingTruck = new Semaphore(1, true);

    // Statistics
    private static final List<Long> waitTimes = Collections.synchronizedList(new ArrayList<>());
    private static final AtomicInteger totalPassengers = new AtomicInteger(0);
    private static final AtomicInteger planesServed = new AtomicInteger(0);

    static class Airplane extends Thread {
        private final int id;
        private final boolean emergency;
        private final long arrivalTime;

        public Airplane(int id, boolean emergency) {
            this.id = id;
            this.emergency = emergency;
            this.arrivalTime = System.currentTimeMillis();
        }

        @Override
        public void run() {
            try {
                System.out.println("Plane " + id + (emergency ? " [EMERGENCY]" : "") + " requesting landing.");

                // High priority for emergency planes simulated by acquiring ground capacity immediately if possible
                if (emergency) {
                    System.out.println("ATC prioritising emergency Plane " + id);
                }

                groundCapacity.acquire();
                runway.acquire();
                long waitTime = System.currentTimeMillis() - arrivalTime;
                waitTimes.add(waitTime);

                System.out.println("Plane " + id + " landing on runway. Wait time: " + waitTime + "ms");
                Thread.sleep(500); // Landing time
                runway.release();

                gates.acquire();
                System.out.println("Plane " + id + " docked at gate.");

                // Concurrent operations at gate
                Thread disembark = new Thread(() -> task("Disembarking", 400));
                Thread supply = new Thread(() -> task("Refilling supplies", 300));
                disembark.start();
                supply.start();

                // Exclusive refueling
                refuelingTruck.acquire();
                System.out.println("Plane " + id + " is refueling exclusively.");
                Thread.sleep(600);
                refuelingTruck.release();

                disembark.join();
                supply.join();

                int passengers = new Random().nextInt(150) + 50;
                totalPassengers.addAndGet(passengers);
                System.out.println("Plane " + id + " boarded " + passengers + " passengers.");

                // Departure
                runway.acquire();
                gates.release();
                System.out.println("Plane " + id + " taking off.");
                Thread.sleep(500);
                runway.release();
                groundCapacity.release();

                planesServed.incrementAndGet();
                System.out.println("Plane " + id + " has left the airport.");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        private void task(String name, int time) {
            try {
                System.out.println("Plane " + id + ": " + name);
                Thread.sleep(time);
            } catch (InterruptedException ignored) {}
        }
    }

    public static void main(String[] args) throws InterruptedException {
        System.out.println("--- Airport Simulation Start ---");

        // Congested Scenario: 2 waiting, 2 occupying gates, 1 emergency
        Airplane[] initialPlanes = new Airplane[5];
        for (int i = 1; i <= 5; i++) {
            initialPlanes[i-1] = new Airplane(i, i == 5);
            initialPlanes[i-1].start();
            Thread.sleep(100); // Staggered arrival
        }

        for (Airplane p : initialPlanes) p.join();

        System.out.println("\n--- ATC Manager Statistics ---");
        System.out.println("Total Planes Served: " + planesServed.get());
        System.out.println("Total Passengers: " + totalPassengers.get());
        if (!waitTimes.isEmpty()) {
            System.out.println("Max Wait: " + Collections.max(waitTimes) + "ms");
            System.out.println("Min Wait: " + Collections.min(waitTimes) + "ms");
            System.out.println("Avg Wait: " + waitTimes.stream().mapToLong(Long::longValue).average().orElse(0) + "ms");
        }
    }
}
